class Spieler:
    def __init__(self, name):
        self.name = name
        self.punkte = 0

    def treffer(self, wert):
        self.punkte += wert
        return self.punkte

s = Spieler("Lisa")
s.treffer(10)
print(s.name, s.treffer(15))

class Geraet:
    def einschalten(self):
        print("Gerät an")

class Handy(Geraet):
    def einschalten(self):
        super().einschalten()
        print("Handy an")

Handy().einschalten()

class Kurs:
    def __init__(self, fach):
        self.fach = fach

class Schularbeit(Kurs):
    def __init__(self, fach, note):
        super().__init__()
        self.note = note

s = Schularbeit("Mathe", 4)
print(s.fach, s.note)

class Hand:
    def __init__(self, karten):
        self.karten = karten

    def __len__(self):
        return len(self.karten)

    def __eq__(self, other):
        return sorted(self.karten) == sorted(other.karten)

h1 = Hand(["Ass", "König", "Dame"])
h2 = Hand(["Dame", "Ass", "König"])
print(len(h1), h1 == h2)

class Temp:
    def __init__(self, grad):
        self.grad = grad

    def __str__(self):
        return f"{self.grad} °C"

    def __repr__(self):
        return f"Temp({self.grad})"

t = Temp(25)
print(t)

class Quadrat:
    def __init__(self, seite):
        self.seite = seite

    @property
    def umfang(self):
        return 4 * self.seite

q = Quadrat(3)
q.umfang = 12
print(q.seite)
